import { test, expect } from '@playwright/test';

test.describe('Dropdown Menu Keyboard Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dropdown-menu');
  });

  test('should navigate dropdown items using keyboard arrow keys', async ({ page }) => {
    // Verify dropdown is visible
    const dropdown = page.getByRole('button', { name: /dropdown/i });
    await expect(dropdown).toBeVisible();

    // Verify initial dropdown item is visible
    const firstItem = page.getByRole('option', { name: /first item/i });
    await expect(firstItem).toBeVisible();

    // Verify dropdown menu is open
    const menu = page.locator('[data-testid="dropdown-menu"]');
    await expect(menu).toBeVisible();

    // Verify dropdown menu has correct number of items
    const itemCount = page.locator('[data-testid="dropdown-item"]').count();
    expect(itemCount).toBeGreaterThan(0);

    // Navigate to the last item using right arrow key
    const rightArrow = page.getByRole('keyboard-region', { name: /arrow key/i });
    await rightArrow.press('ArrowRight');

    // Verify last item is now selected
    const lastItem = page.getByRole('option', { name: /last item/i });
    await expect(lastItem).toBeSelected();

    // Verify dropdown menu is still open
    await expect(menu).toBeVisible();

    // Navigate to the first item using left arrow key
    await rightArrow.press('ArrowLeft');

    // Verify first item is now selected
    await expect(firstItem).toBeSelected();

    // Verify dropdown menu is still open
    await expect(menu).toBeVisible();

    // Navigate to the second item using down arrow key
    await rightArrow.press('ArrowDown');

    // Verify second item is now selected
    const secondItem = page.getByRole('option', { name: /second item/i });
    await expect(secondItem).toBeSelected();

    // Verify dropdown menu is still open
    await expect(menu).toBeVisible();

    // Navigate to the third item using up arrow key
    await rightArrow.press('ArrowUp');

    // Verify third item is now selected
    const thirdItem = page.getByRole('option', { name: /third item/i });
    await expect(thirdItem).toBeSelected();

    // Verify dropdown menu is still open
    await expect(menu).toBeVisible();

    // Navigate to the first item again using left arrow key
    await rightArrow.press('ArrowLeft');

    // Verify first item is now selected again
    await expect(firstItem).toBeSelected();

    // Verify dropdown menu is still open
    await expect(menu).toBeVisible();
  });

  test('should close dropdown when pressing escape key', async ({ page }) => {
    // Open dropdown by clicking the button
    const dropdownButton = page.getByRole('button', { name: /dropdown/i });
    await dropdownButton.click();

    // Verify dropdown menu is open
    const menu = page.locator('[data-testid="dropdown-menu"]');
    await expect(menu).toBeVisible();

    // Verify dropdown menu has items
    const itemCount = page.locator('[data-testid="dropdown-item"]').count();
    expect(itemCount).toBeGreaterThan(0);

    // Press escape key to close dropdown
    const escapeKey = page.getByRole('keyboard-region', { name: /escape key/i });
    await escapeKey.press('Escape');

    // Verify dropdown menu is no longer visible
    await expect(menu).not.toBeVisible();

    // Verify dropdown button is now visible
    await expect(dropdownButton).toBeVisible();

    // Verify dropdown menu has no items
    const itemCountAfterClose = page.locator('[data-testid="dropdown-item"]').count();
    expect(itemCountAfterClose).toBe(0);
  });
});
